PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE classes (
            class_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            description TEXT,
            icon_path TEXT,
            str_base INTEGER DEFAULT 0,
            int_base INTEGER DEFAULT 0,
            dex_base INTEGER DEFAULT 0
        , class_code TEXT);
CREATE TABLE skills (
            skill_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            alias TEXT,
            icon_x INTEGER DEFAULT 0,
            icon_y INTEGER DEFAULT 0,
            icon_w INTEGER DEFAULT 0,
            icon_h INTEGER DEFAULT 0,
            class_id INTEGER,
            type TEXT, skill_code TEXT,
            FOREIGN KEY (class_id) REFERENCES classes(class_id) ON DELETE RESTRICT
        );
CREATE TABLE synergies (
            synergy_id INTEGER PRIMARY KEY AUTOINCREMENT,
            class_id INTEGER,
            name TEXT NOT NULL,
            activation_sequence TEXT,
            recommendation TEXT,
            FOREIGN KEY (class_id) REFERENCES classes(class_id) ON DELETE RESTRICT
        );
CREATE TABLE synergy_effects (
            effect_id INTEGER PRIMARY KEY AUTOINCREMENT,
            synergy_id INTEGER,
            stat TEXT NOT NULL,
            value REAL,
            duration REAL,
            target TEXT,
            value_text TEXT,
            duration_text TEXT,
            FOREIGN KEY (synergy_id) REFERENCES synergies(synergy_id) ON DELETE CASCADE
        );
CREATE TABLE class_skill_assignments (
            class_id INTEGER NOT NULL,
            skill_id INTEGER NOT NULL,
            category TEXT NOT NULL,
            source_ref TEXT NOT NULL,
            is_recommended INTEGER NOT NULL DEFAULT 0,
            PRIMARY KEY (class_id, skill_id),
            FOREIGN KEY (class_id) REFERENCES classes(class_id) ON DELETE CASCADE,
            FOREIGN KEY (skill_id) REFERENCES skills(skill_id) ON DELETE CASCADE
        );
CREATE TABLE scans (
            scan_id INTEGER PRIMARY KEY AUTOINCREMENT,
            monster_id TEXT,
            skill_id INTEGER,
            class_id INTEGER,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
            status TEXT,
            FOREIGN KEY (monster_id) REFERENCES monsters(id) ON DELETE CASCADE,
            FOREIGN KEY (skill_id) REFERENCES skills(skill_id) ON DELETE RESTRICT,
            FOREIGN KEY (class_id) REFERENCES classes(class_id) ON DELETE RESTRICT
        );
CREATE TABLE builds (
            build_id INTEGER PRIMARY KEY AUTOINCREMENT,
            class_id INTEGER,
            author TEXT,
            description TEXT,
            upvote_count INTEGER DEFAULT 0,
            FOREIGN KEY (class_id) REFERENCES classes(class_id) ON DELETE RESTRICT
        );
CREATE TABLE skill_presets (
            preset_id INTEGER PRIMARY KEY AUTOINCREMENT,
            class_id INTEGER NOT NULL,
            name TEXT NOT NULL,
            is_default BOOLEAN DEFAULT FALSE,
            description TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(class_id, name, is_default),
            FOREIGN KEY(class_id) REFERENCES classes(class_id) ON DELETE CASCADE
        );
CREATE TABLE preset_skills (
            preset_skill_id INTEGER PRIMARY KEY AUTOINCREMENT,
            preset_id INTEGER NOT NULL,
            skill_id INTEGER NOT NULL,
            lane_type TEXT NOT NULL,
            position INTEGER NOT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(preset_id) REFERENCES skill_presets(preset_id) ON DELETE CASCADE,
            FOREIGN KEY(skill_id) REFERENCES skills(skill_id) ON DELETE CASCADE,
            UNIQUE(preset_id, lane_type, position)
        );
CREATE TABLE user_preset_state (
            state_id INTEGER PRIMARY KEY AUTOINCREMENT,
            class_id INTEGER NOT NULL UNIQUE,
            active_preset_id INTEGER,
            preset_mode TEXT DEFAULT 'default',
            last_applied TIMESTAMP,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY(class_id) REFERENCES classes(class_id) ON DELETE CASCADE,
            FOREIGN KEY(active_preset_id) REFERENCES skill_presets(preset_id) ON DELETE SET NULL
        );
CREATE TABLE icons (
            icon_key TEXT PRIMARY KEY UNIQUE NOT NULL,
            name TEXT,
            filepath TEXT,
            fallback_emoji TEXT,
            tooltip_translation_key TEXT,
            category TEXT NOT NULL DEFAULT 'General',
            description TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE icon_usages (
            usage_id INTEGER PRIMARY KEY AUTOINCREMENT,
            icon_key TEXT NOT NULL,
            module_name TEXT,
            ui_component_type TEXT,
            ui_element_id TEXT,
            description TEXT,
            FOREIGN KEY(icon_key) REFERENCES icons(icon_key) ON DELETE CASCADE
        );
CREATE TABLE translations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                namespace TEXT NOT NULL,
                key TEXT NOT NULL,
                lang TEXT NOT NULL,
                text TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                UNIQUE(namespace, key, lang)
            );
CREATE TABLE dungeons (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL
            );
CREATE TABLE monster_type (
                value TEXT PRIMARY KEY,
                label TEXT NOT NULL
            );
CREATE TABLE monsters (
                id TEXT PRIMARY KEY,
                name TEXT,
                level INTEGER,
                exp INTEGER,
                hp INTEGER,
                defense INTEGER,
                attackRate INTEGER,
                defenseRate INTEGER,
                hpRecharge INTEGER,
                accuracy INTEGER,
                penetration INTEGER,
                damageReduction INTEGER,
                evasion INTEGER,
                resistCritRate INTEGER,
                primaryAttackMin INTEGER,
                primaryAttackMax INTEGER,
                secondaryAttackMin INTEGER,
                secondaryAttackMax INTEGER,
                ignoreAccuracy INTEGER,
                ignoreDamageReduction INTEGER,
                ignorePenetration INTEGER,
                absoluteDamage INTEGER,
                resistSkillAmp INTEGER,
                resistCritDamage INTEGER,
                resistSuppress INTEGER,
                resistSilence INTEGER,
                resistDiffDamage INTEGER,
                hpProportionDamage INTEGER,
                serverBossType TEXT,
                dungeonId TEXT,
                FOREIGN KEY (dungeonId) REFERENCES dungeons(id) ON DELETE SET NULL,
                FOREIGN KEY (serverBossType) REFERENCES monster_type(value) ON DELETE SET NULL
            );
CREATE INDEX idx_csa_class_id ON class_skill_assignments(class_id);
CREATE INDEX idx_csa_skill_id ON class_skill_assignments(skill_id);
CREATE INDEX idx_presets_class ON skill_presets(class_id);
CREATE INDEX idx_presets_default ON skill_presets(is_default);
CREATE INDEX idx_preset_skills_preset ON preset_skills(preset_id);
CREATE INDEX idx_preset_skills_skill ON preset_skills(skill_id);
CREATE INDEX idx_monsters_dungeonId ON monsters(dungeonId);
CREATE INDEX idx_monsters_serverBossType ON monsters(serverBossType);
CREATE UNIQUE INDEX idx_classes_class_code ON classes(class_code) WHERE class_code IS NOT NULL;
COMMIT;

