INSERT INTO translations VALUES(9,'_global','help_hunt_title','en','1. Hunt Screen Reminders','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(10,'_global','help_hunt_desc','en',unistr('• Select Window: Remember to select the correct game window from the Top Bar before starting.\u000a• Target Check: Ensure the target template is correct. If detection is slow or inaccurate, reduce the search region.\u000a• Start Hunt: Check skill configurations and timings before clicking Start Hunt.'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(11,'_global','help_setup_title','en','2. Setup Screen Reminders','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(12,'_global','help_setup_desc','en',unistr('• Skill Config: Make sure to save your skill assignments.\u000a• Timing: Verify cast times and cooldowns to prevent the bot from getting stuck waiting for skills.\u000a• Auto Repair/HP: Check these options if you need out-of-combat assistance.'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(13,'_global','help_stats_title','en','3. Stats & Logs Reminders','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(14,'_global','help_stats_desc','en','• Monitoring: Check the logs to understand why the bot stopped (e.g., lost target, stuck skills).','2026-09-15T20:13:21.097926');
