INSERT INTO translations VALUES(159,'_global','help_about','en','About','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(160,'_global','help_about_text','en',unistr('Cabal Auto Manager v1.0\u000a\u000aAuthor: SokKimThanh\u000aGitHub: github.com/SokKimThanh/Cabal_Auto\u000a\u000aBuilt with Python, tkinter, OpenCV'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(161,'_global','help_quickstart','en','Quick Start Guide','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(162,'_global','help_quickstart_text','en',unistr('1. Click "Find Windows" to list game windows\u000a2. Select your game window from dropdown\u000a3. Configure monsters and skills in Setup tab\u000a4. Click "Start Hunt" to begin\u000a5. Press Ctrl+Shift+R to start or Ctrl+Shift+E to stop hunt anytime'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(163,'_global','help_shortcuts','en','Keyboard Shortcuts','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(164,'_global','help_shortcuts_text','en',unistr('Application Shortcuts:\u000a⌨️  Ctrl+K → Open Skill Manager\u000a⌨️  Alt+1 → Switch to Hunt tab\u000a⌨️  Alt+2 → Switch to Setup tab\u000a⌨️  Ctrl+Shift+R → Start Hunt (global hotkey)\u000a⌨️  Ctrl+Shift+E → Stop Hunt (global hotkey)\u000a\u000aIn-Game Controls:\u000a🎮  Z → Target next monster\u000a🎮  1-6 → Use skills (skill slots)\u000a🎮  Attack Keys → Attack current target\u000a\u000aTips:\u000a• Use Ctrl+Shift+R/E for quick hunt start/stop without mouse\u000a• Ctrl+K opens skill manager from anywhere\u000a• Global hotkeys work even when app is minimized\u000a• Customize hotkeys in Setup → Global Hotkeys section'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(165,'_global','help_troubleshooting','en','Troubleshooting','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(166,'_global','help_troubleshooting_text','en',unistr('Q: Hunt not working?\u000aA: Make sure game window is selected and brought to front.\u000a\u000aQ: Skills not casting?\u000aA: Check skill slots are enabled and cooldowns are correct.\u000a\u000aQ: Can''t find monster?\u000aA: Try lowering template threshold in Setup tab.'),'2026-09-15T20:13:21.097926');
