INSERT INTO translations VALUES(684,'_global','help_hunt_title','vi','1. Nhắc nhở Màn hình Hunt','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(685,'_global','help_hunt_desc','vi',unistr('• Chọn Cửa sổ: Nhớ chọn đúng cửa sổ game ở thanh trên cùng (Top Bar) trước khi bắt đầu.\u000a• Kiểm tra Mục tiêu: Đảm bảo ảnh mẫu mục tiêu (target template) chính xác. Nếu nhận diện chậm/sai, hãy thu hẹp vùng chọn.\u000a• Bắt đầu: Kiểm tra cấu hình kĩ năng và thời gian trước khi nhấn Bắt đầu (Start Hunt).'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(686,'_global','help_setup_title','vi','2. Nhắc nhở Màn hình Thiết lập','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(687,'_global','help_setup_desc','vi',unistr('• Cấu hình Kĩ năng: Đảm bảo đã lưu các thiết lập kĩ năng.\u000a• Thời gian (Timing): Kiểm tra thời gian cast và hồi chiêu để tránh tình trạng treo bot do chờ kĩ năng.\u000a• Tự động Sửa đồ/HP: Đánh dấu nếu bạn cần bot hỗ trợ khi ngoài giao tranh.'),'2026-09-15T20:13:21.097926');
