INSERT INTO translations VALUES(842,'_global','help_about','vi','Thông tin','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(843,'_global','help_about_text','vi',unistr('Trợ lý săn Cabal v1.0\u000a\u000aTác giả: SokKimThanh\u000aGitHub: github.com/SokKimThanh/Cabal_Auto\u000a\u000aXây dựng với Python, tkinter, OpenCV'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(844,'_global','help_quickstart','vi','Hướng dẫn nhanh','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(845,'_global','help_quickstart_text','vi',unistr('1. Nhấn "Tìm cửa sổ" để liệt kê cửa sổ game\u000a2. Chọn cửa sổ game từ danh sách\u000a3. Cấu hình quái vật và kỹ năng trong tab Thiết lập\u000a4. Nhấn "Bắt đầu săn" để bắt đầu\u000a5. Nhấn Ctrl+Shift+R để bắt đầu hoặc Ctrl+Shift+E để dừng săn bất cứ lúc nào'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(846,'_global','help_shortcuts','vi','Phím tắt','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(847,'_global','help_shortcuts_text','vi',unistr('Phím tắt ứng dụng:\u000a⌨️  Ctrl+K → Mở Quản lý Kỹ năng\u000a⌨️  Alt+1 → Chuyển sang tab Săn\u000a⌨️  Alt+2 → Chuyển sang tab Thiết lập\u000a⌨️  Ctrl+Shift+R → Bắt đầu Săn (hotkey toàn cục)\u000a⌨️  Ctrl+Shift+E → Dừng Săn (hotkey toàn cục)\u000a\u000aĐiều khiển trong game:\u000a🎮  Z → Chọn quái tiếp theo\u000a🎮  1-6 → Sử dụng kỹ năng (skill slots)\u000a🎮  Phím tấn công → Đánh mục tiêu hiện tại\u000a\u000aMẹo:\u000a• Dùng Ctrl+Shift+R/E để bắt đầu/dừng săn nhanh\u000a• Ctrl+K mở quản lý kỹ năng từ bất kỳ đâu\u000a• Phím tắt toàn cục hoạt động khi ứng dụng thu nhỏ'),'2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(848,'_global','help_troubleshooting','vi','Xử lý sự cố','2026-09-15T20:13:21.097926');
INSERT INTO translations VALUES(849,'_global','help_troubleshooting_text','vi',unistr('Q: Săn không hoạt động?\u000aA: Đảm bảo cửa sổ game đã được chọn và đưa lên trước.\u000a\u000aQ: Kỹ năng không ra?\u000aA: Kiểm tra skill slots đã bật và cooldown đúng chưa.\u000a\u000aQ: Không tìm thấy quái?\u000aA: Thử giảm threshold trong tab Thiết lập.'),'2026-09-15T20:13:21.097926');
